  /**
   * Authenticate user with email and password
   */
  async authenticateWithCredentials(
    email: string,
    password: string,
    tenantSlug?: string
  ): Promise<any | null> {
    try {
      // Find user by email
      const user = await prisma.user.findUnique({
        where: { email },
        include: {
          organization: true,
          accounts: true
        }
      });

      if (!user) {
        return null;
      }

      // Check if user has a password (credentials account)
      const credentialsAccount = user.accounts.find(
        account => account.provider === "credentials"
      );

      if (!credentialsAccount || !credentialsAccount.accessToken) {
        return null;
      }

      // Verify password
      const isValidPassword = await compare(password, credentialsAccount.accessToken);
      if (!isValidPassword) {
        return null;
      }

      // Check tenant access if tenantSlug provided
      if (tenantSlug && user.organization.slug !== tenantSlug) {
        return null;
      }

      // Check if user is active
      if (user.status !== "active") {
        return null;
      }

      return {
        id: user.id,
        email: user.email,
        name: user.name,
        tenantId: user.tenantId,
        tenantSlug: user.organization.slug
      };
    } catch (error) {
      console.error("Authentication error:", error);
      return null;
    }
  }

  /**
   * Create new user with password
   */
  async createUserWithPassword(
    email: string,
    password: string,
    name: string,
    tenantId: string
  ): Promise<any> {
    try {
      // Hash password
      const hashedPassword = await hash(password, 12);

      // Create user
      const user = await prisma.user.create({
        data: {
          email,
          name,
          tenantId,
          emailVerified: null, // Will be set when email is verified
        },
        include: {
          organization: true
        }
      });

      // Create credentials account
      await prisma.account.create({
        data: {
          userId: user.id,
          type: "credentials",
          provider: "credentials",
          providerAccountId: user.id,
          accessToken: hashedPassword
        }
      });

      return user;
    } catch (error) {
      console.error("User creation error:", error);
      throw error;
    }
  }

  /**
   * Check if user has access to tenant
   */
  async checkUserTenantAccess(email: string, tenantId: string): Promise<boolean> {
    try {
      const user = await prisma.user.findUnique({
        where: { email },
        include: {
          memberships: {
            where: {
              organizationId: tenantId,
              status: "active"
            }
          }
        }
      });

      // Check if user belongs to this tenant or has cross-tenant permissions
      return user?.tenantId === tenantId || user?.memberships.length! > 0;
    } catch (error) {
      console.error("Tenant access check error:", error);
      return false;
    }
  }

  /**
   * Get enhanced user information with roles and permissions
   */
  async getEnhancedUserInfo(userId: string): Promise<EnhancedUserInfo | null> {
    try {
      const user = await prisma.user.findUnique({
        where: { id: userId },
        include: {
          organization: true,
          roles: {
            include: {
              role: {
                include: {
                  permissions: {
                    include: {
                      permission: true
                    }
                  }
                }
              }
            }
          },
          personas: {
            where: { isActive: true },
            include: {
              persona: true
            }
          },
          sessionContexts: {
            orderBy: { updatedAt: "desc" },
            take: 1,
            include: {
              activePersona: true
            }
          }
        }
      });

      if (!user) {
        return null;
      }

      // Collect all permissions from roles
      const permissions = new Set<string>();
      const roles = user.roles.map(userRole => {
        const role = userRole.role;
        const rolePermissions = role.permissions
          .filter(rp => rp.granted)
          .map(rp => rp.permission.name);

        rolePermissions.forEach(permission => permissions.add(permission));

        return {
          id: role.id,
          name: role.name,
          displayName: role.displayName,
          permissions: rolePermissions
        };
      });

      // Map personas
      const personas = user.personas.map(up => ({
        id: up.persona.id,
        name: up.persona.name,
        displayName: up.persona.displayName,
        isDefault: up.isDefault,
        isActive: up.isActive
      }));

      // Get active persona
      const activePersona = user.sessionContexts[0]?.activePersona;

      return {
        id: user.id,
        email: user.email,
        name: user.name,
        tenantId: user.tenantId,
        organization: {
          id: user.organization.id,
          name: user.organization.name,
          slug: user.organization.slug
        },
        status: user.status,
        roles,
        personas,
        permissions: Array.from(permissions),
        activePersona: activePersona ? {
          id: activePersona.id,
          name: activePersona.name,
          displayName: activePersona.displayName
        } : undefined
      };
    } catch (error) {
      console.error("Enhanced user info error:", error);
      return null;
    }
  }

  /**
   * Update user's last login time
   */
  async updateLastLogin(userId: string): Promise<void> {
    try {
      await prisma.user.update({
        where: { id: userId },
        data: {
          lastLogin: new Date(),
          loginCount: {
            increment: 1
          }
        }
      });
    } catch (error) {
      console.error("Update last login error:", error);
    }
  }

  /**
   * Update session activity
   */
  async updateSessionActivity(userId: string): Promise<void> {
    try {
      // Update session context timestamp
      await prisma.userSessionContext.updateMany({
        where: { userId },
        data: { updatedAt: new Date() }
      });
    } catch (error) {
      console.error("Session activity update error:", error);
    }
  }

  /**
   * Cleanup session context on logout
   */
  async cleanupSessionContext(userId: string): Promise<void> {
    try {
      // Remove old session contexts (older than 24 hours)
      const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

      await prisma.userSessionContext.deleteMany({
        where: {
          userId,
          updatedAt: {
            lt: oneDayAgo
          }
        }
      });
    } catch (error) {
      console.error("Session cleanup error:", error);
    }
  }

