  /**
   * Generate password reset token
   */
  async generatePasswordResetToken(email: string): Promise<string | null> {
    try {
      const user = await prisma.user.findUnique({
        where: { email }
      });

      if (!user) {
        return null;
      }

      // Generate secure token
      const token = this.securityService.generateSecureToken();
      const expires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

      // Store reset token
      await prisma.verificationToken.create({
        data: {
          identifier: email,
          token: createHash("sha256").update(token).digest("hex"),
          expires
        }
      });

      return token;
    } catch (error) {
      console.error("Password reset token generation error:", error);
      return null;
    }
  }

  /**
   * Reset user password with token
   */
  async resetPasswordWithToken(
    token: string,
    email: string,
    newPassword: string
  ): Promise<boolean> {
    try {
      const hashedToken = createHash("sha256").update(token).digest("hex");

      // Find valid token
      const verificationToken = await prisma.verificationToken.findUnique({
        where: {
          identifier_token: {
            identifier: email,
            token: hashedToken
          }
        }
      });

      if (!verificationToken || verificationToken.expires < new Date()) {
        return false;
      }

      // Hash new password
      const hashedPassword = await hash(newPassword, 12);

      // Update user's credentials account
      const user = await prisma.user.findUnique({
        where: { email },
        include: { accounts: true }
      });

      if (!user) {
        return false;
      }

      const credentialsAccount = user.accounts.find(
        account => account.provider === "credentials"
      );

      if (credentialsAccount) {
        await prisma.account.update({
          where: { id: credentialsAccount.id },
          data: { accessToken: hashedPassword }
        });
      } else {
        // Create credentials account if it doesn't exist
        await prisma.account.create({
          data: {
            userId: user.id,
            type: "credentials",
            provider: "credentials",
            providerAccountId: user.id,
            accessToken: hashedPassword
          }
        });
      }

      // Remove used token
      await prisma.verificationToken.delete({
        where: {
          identifier_token: {
            identifier: email,
            token: hashedToken
          }
        }
      });

      // Log password reset
      await this.auditService.logAuthEvent({
        eventType: "password_reset",
        userId: user.id,
        tenantId: user.tenantId,
        email
      });

      return true;
    } catch (error) {
      console.error("Password reset error:", error);
      return false;
    }
  }

  /**
   * Change user password
   */
  async changePassword(
    userId: string,
    currentPassword: string,
    newPassword: string
  ): Promise<boolean> {
    try {
      const user = await prisma.user.findUnique({
        where: { id: userId },
        include: { accounts: true }
      });

      if (!user) {
        return false;
      }

      const credentialsAccount = user.accounts.find(
        account => account.provider === "credentials"
      );

      if (!credentialsAccount || !credentialsAccount.accessToken) {
        return false;
      }

      // Verify current password
      const isValidPassword = await compare(
        currentPassword,
        credentialsAccount.accessToken
      );

      if (!isValidPassword) {
        return false;
      }

      // Hash new password
      const hashedPassword = await hash(newPassword, 12);

      // Update password
      await prisma.account.update({
        where: { id: credentialsAccount.id },
        data: { accessToken: hashedPassword }
      });

      // Log password change
      await this.auditService.logAuthEvent({
        eventType: "password_changed",
        userId: user.id,
        tenantId: user.tenantId
      });

      return true;
    } catch (error) {
      console.error("Password change error:", error);
      return false;
    }
  }

